def wrap_greedy(text, width):
    words = text.split()
    if not words:
        return []
    lines = []
    start = 0
    i = 1
    while i <= len(words):
        candidate = ' '.join(words[start:i])
        if len(candidate) <= width:
            i += 1
        elif i - 1 > start:
            lines.append(' '.join(words[start:i - 1]))
            start = i - 1
        else:
            lines.append(words[start])
            start += 1
            i = start + 1
    if start < len(words):
        lines.append(' '.join(words[start:]))
    return lines

