def is_valid_pin_code(s):
    if len(s) != 4 or not s.isdigit():
        return False
    digits = [int(c) for c in s]
    if len(set(digits)) == 1:
        return False
    diffs = [b - a for a, b in zip(digits, digits[1:])]
    if all(d == 1 for d in diffs) or all(d == -1 for d in diffs):
        return False
    return True

