def is_semiperfect_number(n):
    if n <= 0:
        return False
    divisors = [i for i in range(1, n) if n % i == 0]
    reachable = [False] * (n + 1)
    reachable[0] = True
    for d in divisors:
        for total in range(n, d - 1, -1):
            if reachable[total - d]:
                reachable[total] = True
    return reachable[n]

