def weekday_from_date_string(date_str):
    y, m, d = (int(p) for p in date_str.split('-'))
    def days_before_year(year):
        y1 = year - 1
        return y1 * 365 + y1 // 4 - y1 // 100 + y1 // 400
    def is_leap(year):
        return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
    days_in_month = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    days = days_before_year(y)
    for i in range(m - 1):
        days += days_in_month[i]
        if i == 1 and is_leap(y):
            days += 1
    days += d
    names = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
    return names[(days - 1) % 7]

def is_valid_wildcard_mask(s):
    parts = s.split('.')
    if len(parts) != 4:
        return False
    octets = []
    for p in parts:
        if not p.isdigit() or int(p) > 255:
            return False
        octets.append(int(p))
    value = 0
    for o in octets:
        value = (value << 8) | o
    return (value & (value + 1)) == 0

def count_valid_dates_in_list(date_list):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    month_days = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    count = 0
    for s in date_list:
        parts = s.split('-')
        if len(parts) != 3:
            continue
        y_s, m_s, d_s = parts
        if len(y_s) != 4 or len(m_s) != 2 or len(d_s) != 2:
            continue
        if not (y_s.isdigit() and m_s.isdigit() and d_s.isdigit()):
            continue
        y, m, d = int(y_s), int(m_s), int(d_s)
        if m < 1 or m > 12:
            continue
        limit = 29 if (m == 2 and is_leap(y)) else month_days[m - 1]
        if 1 <= d <= limit:
            count += 1
    return count

